{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE redtape_db.Maplemonk.redtape_db_flipkart_margin_fact_items as SELECT EAN, SKU, ARTICLE, FLIPKART_CATEGORY, UPPER(FKT.CATEGORY_NAME) CATEGORY, SAP_CATEGORY, GENDER, LENGTH_CM, HEIGHT_CM, WIDTH_CM, WEIGHT_KG, VOLUME_WEIGHT, CHARGEABLE_WEIGHT, AVAILABLE_QUANTITY, MRP, COST, TYPE, LEVEL, MULTIPLE, \"DISCOUNT_%\", ROUND(BILL_VALUE,2) BILL_VALUE, \"GST_%\", ROUND(SALE_VALUE,2) SALE_VALUE, WEIGHT_SLAB_HELPER, PRICE_SLAB_HELPER, MAIN_HELPER, \"Fixed Fee\" FIXED_FEE, ROUND(COALESCE(NEW_GTA_VALUE,0),2) AS TOTAL_GTA, Round(COALESCE(BILL_VALUE, 0) - COALESCE(TOTAL_GTA, 0),2) AS BILL_VALUE_AFTER_GTA, CASE WHEN BILL_VALUE_AFTER_GTA < 2625 THEN 5 ELSE 18 END AS \"GST2_%\", ROUND((BILL_VALUE_AFTER_GTA * 100 / NULLIF(100 + \"GST2_%\", 0)),2) AS SALE_VALUE_AFTER_GTA, \"REBATE_%\", ROUND(COALESCE((\"REBATE_%\" / 100.0),0) * COALESCE(BILL_VALUE_AFTER_GTA,0),2) AS REBATE_AMOUNT, COALESCE((SALE_VALUE_AFTER_GTA + REBATE_AMOUNT),0) AS SALE_VALUE_REBATE, ROUND(COALESCE(SALE_VALUE_REBATE, 0) - COALESCE(COST, 0),2) AS GROSS_MARGIN, ROUND((GROSS_MARGIN / NULLIF(COALESCE(SALE_VALUE_REBATE,0),0)) * 100,2) AS \"GROSS_MARGIN%\", \"Commission %\" AS \"COMMISSION_%\", ROUND((COALESCE(BILL_VALUE_AFTER_GTA,0) * COALESCE(\"COMMISSION_%\"/100,0)),2) AS COMMISSION_VALUE, \"COURIER_RET%\", \"CUSTOMER_RET%\", ROUND( (( COALESCE(REV.LOCAL,0) * ZS.LOCAL/100 + COALESCE(REV.ZONAL,0) * ZS.ZONAL/100 + COALESCE(REV.NATIONAL,0) * ZS.NATIONAL/100) * COALESCE(\"CUSTOMER_RET%\",0) / 100) / NULLIF((100 - COALESCE(\"COURIER_RET%\",0) - COALESCE(\"CUSTOMER_RET%\",0)) / 100,0),2) AS REV_FRT, ROUND(COALESCE(FIXED_FEE,0) + (COALESCE(FIXED_FEE,0) * COALESCE(\"CUSTOMER_RET%\",0) / NULLIF(100 - COALESCE(\"COURIER_RET%\",0) - COALESCE(\"CUSTOMER_RET%\",0),0)), 2) AS TOTAL_FIXED_FEE, ROUND((5/((100-\"COURIER_RET%\"-\"CUSTOMER_RET%\")/100)),2) AS PACKING, ROUND((COALESCE(SALE_VALUE_AFTER_GTA,0)*(2/100)),2) AS ADVERTISEMET, ROUND((COALESCE(SALE_VALUE_AFTER_GTA,0)*(7.5/100)),2) AS COMMON, ROUND(COALESCE(COMMISSION_VALUE,0)+COALESCE(REV_FRT,0)+COALESCE(PACKING,0)+COALESCE(ADVERTISEMET,0)+COALESCE(COMMON,0)+COALESCE(TOTAL_FIXED_FEE,0),2) AS TOTAL_EXPENSES, ROUND(((COALESCE(TOTAL_EXPENSES,0) / NULLIF(COALESCE(SALE_VALUE_REBATE,0),0)) * 100),2) AS \"EXPENSES_%\", ROUND(COALESCE(GROSS_MARGIN,0) - COALESCE(TOTAL_EXPENSES,0) + COALESCE(REBATE_AMOUNT,0),2) AS NET_MARGIN, ROUND((COALESCE(NET_MARGIN,0) / NULLIF(COALESCE(SALE_VALUE_REBATE,0),0) *100),2) AS \"NET_MARGIN%\" FROM( SELECT ISN.*, CASE WHEN CHARGEABLE_WEIGHT <= 0.5 THEN 0.5 WHEN CHARGEABLE_WEIGHT <= 1 THEN 1 WHEN CHARGEABLE_WEIGHT <= 1.5 THEN 1.5 WHEN CHARGEABLE_WEIGHT <= 2 THEN 2 WHEN CHARGEABLE_WEIGHT <= 2.5 THEN 2.5 WHEN CHARGEABLE_WEIGHT <= 3 THEN 3 ELSE 3.1 END AS WEIGHT_SLAB_HELPER, ROUND(COALESCE(ISN.MRP,0) / NULLIF(COST, 0),2) AS MULTIPLE, COALESCE(ISN.MRP,0) - (COALESCE(ISN.MRP,0) * \"DISCOUNT_%\" / 100) AS BILL_VALUE, CASE WHEN BILL_VALUE < 2625 THEN 5 ELSE 18 END AS \"GST_%\", ROUND((BILL_VALUE * 100 / NULLIF(100 + \"GST_%\", 0)),2) AS SALE_VALUE, CASE WHEN BILL_VALUE <= 200 THEN 200 WHEN BILL_VALUE <= 300 THEN 300 WHEN BILL_VALUE <= 500 THEN 500 WHEN BILL_VALUE <= 1000 THEN 1000 WHEN BILL_VALUE <= 1001 THEN 1001 ELSE 10000000 END AS PRICE_SLAB_HELPER, CONCAT_WS(\'-\', FLIPKART_CATEGORY, PRICE_SLAB_HELPER, WEIGHT_SLAB_HELPER) AS MAIN_HELPER FROM ( SELECT COALESCE(B.EAN,REPLACE(REPLACE(A.EANUPC, \'`\', \'\'), \',\', \'\')) EAN, A.SKU, COALESCE(REGEXP_REPLACE(REPLACE(SKU,\'`\',\'\'), \'-[^-]*$\', \'\'),A.ARTICLES) ARTICLE, A.LENGTH AS LENGTH_CM, A.HEIGHT AS HEIGHT_CM, A.WIDTH AS WIDTH_CM, A.WEIGHT, ROUND(COALESCE(TRY_TO_DOUBLE(A.WEIGHT),0) / 1000.0,2) AS WEIGHT_KG, ROUND(( COALESCE(TRY_TO_DOUBLE(A.LENGTH),0) * COALESCE(TRY_TO_DOUBLE(A.HEIGHT),0) * COALESCE(TRY_TO_DOUBLE(A.WIDTH),0)) / 5000.0,2) AS VOLUME_WEIGHT, CASE WHEN VOLUME_WEIGHT > WEIGHT_KG THEN VOLUME_WEIGHT ELSE WEIGHT_KG END AS CHARGEABLE_WEIGHT, 80.0 AS \"DISCOUNT_%\", 15.0 AS \"REBATE_%\", CASE WHEN \"Courier return %\" IS NULL OR \"Courier return %\" = 0 THEN 25 ELSE ROUND(\"Courier return %\", 1) END AS \"COURIER_RET%\", CASE WHEN \"Customer Return %\" IS NULL OR \"Customer Return %\" = 0 THEN 11 ELSE ROUND(\"Customer Return %\", 1)END AS \"CUSTOMER_RET%\", CAST(REPLACE(A.COST, \',\', \'\') AS FLOAT) AS COST, CAST(REPLACE(A.MRP, \',\', \'\') AS FLOAT) AS MRP, A.GENDER, UPPER(A.CATEGORY_NAME) CATEGORY_NAME, A.SAP_CATEGORY, UPPER(A.TYPE) TYPE, UPPER(A.LEVEL) LEVEL, A.FLIPKART_CATEGORY, AVAILABLE_QUANTITY FROM ( SELECT * FROM MAPLEMONK.REDTAPE_DB_MARGIN_PRODUCT_MASTER ) A LEFT JOIN ( SELECT * FROM ( SELECT \"Report Generated Date\"::DATE AS FIRST_DATE, REPLACE(EAN, \'`\', \'\') AS EAN, SUM(\"Available Quantity\") AS AVAILABLE_QUANTITY FROM REDTAPE_DB.MAPLEMONK.EASYECOM_REDTAPE_INVENTORY_SNAPSHOT WHERE \"Report Generated Date\" IS NOT NULL GROUP BY 1,2) QUALIFY ROW_NUMBER() OVER(PARTITION BY EAN ORDER BY FIRST_DATE DESC) = 1) B ON REPLACE(A.EANUPC, \'`\', \'\') = REPLACE(B.EAN, \'`\', \'\') LEFT JOIN( select \"TYPE 2\" TYPE ,GENDER ,\"Courier return %\" ,\"Customer Return %\" from MAPLEMONK.REDTAPE_FLIPKART_MARGIN_COURIER_AND_CUSTOMER_RETURN where UPPER(GENDER) != \'ALL\') CR ON UPPER(REPLACE(TRIM(A.TYPE), \' \', \'\')) = UPPER(REPLACE(TRIM(CR.TYPE), \' \', \'\')) AND UPPER(TRIM(A.GENDER)) = UPPER(TRIM(CR.GENDER)) ) ISN ) FKT LEFT JOIN ( SELECT UPPER(VERTICAL) VERTICAL, START_ASP LOWER_PRICE, END_ASP UPPER_PRICE, START_SHIPPING_SLAB LOWER_WEIGHT, END_SHIPPING_SLAB UPPER_WEIGHT, \"New GTA Value - New\" NEW_GTA_VALUE, \"Fixed Fee\" FROM MAPLEMONK.REDTAPE_FLIPKART_MARGIN_GTA_CHARGES___FIXED_FEE) GTA ON LOWER(FKT.FLIPKART_CATEGORY) = LOWER(GTA.VERTICAL) AND FKT.BILL_VALUE BETWEEN GTA.LOWER_PRICE AND GTA.UPPER_PRICE AND FKT.CHARGEABLE_WEIGHT BETWEEN GTA.LOWER_WEIGHT AND GTA.UPPER_WEIGHT LEFT JOIN ( SELECT \"CMS Vertical\" VERTICAL, TO_DECIMAL(REPLACE(\"Commission %\", \'%\', \'\'), 10, 2) AS \"Commission %\", FROM MAPLEMONK.REDTAPE_FLIPKART_MARGIN_COMMISSION) CMM ON LOWER(FKT.FLIPKART_CATEGORY) = LOWER(CMM.Vertical) LEFT JOIN ( SELECT VERTICAL,LOWER_WEIGHT,UPPER_WEIGHT,LOCAL,ZONAL,NATIONAL FROM MAPLEMONK.REDTAPE_FLIPKART_MARGIN_REVERSE_SHIPPING_CHARGES ) REV ON LOWER(FKT.FLIPKART_CATEGORY)=LOWER(REV.VERTICAL) AND FKT.CHARGEABLE_WEIGHT BETWEEN REV.LOWER_WEIGHT AND REV.UPPER_WEIGHT LEFT JOIN ( SELECT DETAILS ,CAST(REPLACE(LOCAL,\'%\',\'\') AS FLOAT) LOCAL ,CAST(REPLACE(ZONAL,\'%\',\'\') AS FLOAT) ZONAL ,CAST(REPLACE(NATIONAL,\'%\',\'\') AS FLOAT) NATIONAL FROM MAPLEMONK.REDTAPE_FLIPKART_MARGIN_ZONES_SHARE__) ZS ON 1=1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            